raw_meta_yaml:
{% set dataset_name = "INCL" %}
{% set version = "1.3.0" %}
{% set version_canonical_geant4 = "1.3" %}
{% set sha256 = "e4b3dbe52acef53536454e22443091212843821bd23628eed846d299599f3bf9" %}
{% set env_var = "G4INCLDATA" %}
{% set summary = "GEANT4 data files for proton and neutron density profiles in INCL" %}

{% set name = "geant4-data-"+dataset_name.lower() %}
{% set install_dir = "share/Geant4/data/"+dataset_name+version_canonical_geant4 %}

package:
  name: {{ name }}
  version: {{ version }}

source:
  url: https://geant4-data.web.cern.ch/geant4-data/datasets/G4{{ dataset_name }}.{{ version_canonical_geant4 }}.tar.gz
  sha256: {{ sha256 }}
  folder: dataset

build:
  number: 1
  noarch: generic
  script:
    - mkdir -p ${PREFIX}/{{ install_dir }}
    - cp -r dataset/* ${PREFIX}/{{ install_dir }}
    - ${RECIPE_DIR}/create_activation_scripts.sh {{ name }} {{ env_var }} {{ install_dir }}

# Conda-forge is unable to build packages that have no dependencies so add
# `make` as a dummy build dependency
requirements:
  build:
    - make

test:
  commands:
    - '[ "${{ env_var }}" == "$CONDA_PREFIX/{{ install_dir }}" ]'

about:
  home: https://geant4.web.cern.ch/
  summary: {{ summary }}
  license: OTHER
  license_file: CREDIT

extra:
  recipe-maintainers:
    - chrisburr
    - tkittel
